import json


def make_key(job_text, profile_version, criteria_version):
    return json.dumps((job_text, profile_version, criteria_version), separators=(",", ":"))

from service import score


def test_same_inputs_reuse():
    store = {}
    r1 = score(store, "job", "p", "c", lambda: 1)
    assert r1 == 1
    r2 = score(store, "job", "p", "c", lambda: 2)
    assert r2 == 1  # reused even though compute returned a different value


def test_job_text_changes_recompute():
    store = {}
    assert score(store, "job1", "p", "c", lambda: 1) == 1
    assert score(store, "job2", "p", "c", lambda: 2) == 2


def test_profile_version_changes_recompute():
    store = {}
    assert score(store, "job", "p1", "c", lambda: 1) == 1
    assert score(store, "job", "p2", "c", lambda: 2) == 2


def test_criteria_version_changes_recompute():
    store = {}
    assert score(store, "job", "p", "c1", lambda: 1) == 1
    assert score(store, "job", "p", "c2", lambda: 2) == 2


def test_none_inputs_reuse():
    store = {}
    assert score(store, "job", None, None, lambda: 10) == 10
    assert score(store, "job", None, None, lambda: 20) == 10  # reused even with None inputs


def test_none_and_string_inputs_distinct():
    store = {}
    r1 = score(store, "job", None, None, lambda: 100)
    r2 = score(store, "job", "p", "c", lambda: 200)
    assert r1 != r2


def test_ambiguous_concatenation_keys():
    # job text containing colons/dollar signs etc. must not collide with versions
    store = {}
    r1 = score(store, "a:1", "p", None, lambda: 1)
    r2 = score(store, "a", "p1", None, lambda: 2)
    r3 = score(store, "a", None, "1", lambda: 3)
    assert r1 == 1 and r2 == 2 and r3 == 3


if __name__ == "__main__":
    test_same_inputs_reuse()
    test_job_text_changes_recompute()
    test_profile_version_changes_recompute()
    test_criteria_version_changes_recompute()
    test_none_inputs_reuse()
    test_none_and_string_inputs_distinct()
    test_ambiguous_concatenation_keys()
    print("all checks passed")
